IF OBJECT_ID('tempdb..#SessionIDs') IS NULL
BEGIN
    CREATE TABLE #SessionIDs (session_id NVARCHAR(100));
END
BEGIN

    TRUNCATE TABLE #SessionIDs;

    INSERT INTO #SessionIDs (session_id)
    SELECT DISTINCT s.session_id
    FROM sys.dm_pdw_exec_sessions s
    INNER JOIN sys.dm_pdw_exec_requests r
    ON s.session_id = r.session_id
    WHERE r.command LIKE '%sp_infra_gatherstats%'
    AND r.status = 'Running'
    AND s.session_id <> SESSION_ID()
    AND s.login_time < DATEADD(MINUTE, -300, GETDATE());
    DECLARE @session_id NVARCHAR(100);
    WHILE EXISTS (SELECT 1 FROM #SessionIDs)
    BEGIN
        -- Retrieve the next session ID
        SET @session_id = (SELECT TOP 1 session_id FROM #SessionIDs);
        DECLARE @sql_stmt NVARCHAR(MAX) = N'KILL '''+ @session_id + '''';
        EXEC [sp_executesql] @sql_stmt;
        DELETE FROM #SessionIDs WHERE session_id = @session_id;
    END
END
DROP TABLE #SessionIDs;

IF OBJECT_ID('tempdb..#SessionIDs') IS NULL
BEGIN
    CREATE TABLE #SessionIDs (session_id NVARCHAR(100));
END
BEGIN

    TRUNCATE TABLE #SessionIDs;

    INSERT INTO #SessionIDs (session_id)
    SELECT DISTINCT session_id
    FROM sys.dm_pdw_exec_requests
    WHERE command LIKE '%sp_infra_process_orders%'
    AND status = 'Running'
    AND session_id <> SESSION_ID()
    DECLARE @session_id NVARCHAR(100);
    WHILE EXISTS (SELECT 1 FROM #SessionIDs)
    BEGIN
        -- Retrieve the next session ID
        SET @session_id = (SELECT TOP 1 session_id FROM #SessionIDs);
        DECLARE @sql_stmt NVARCHAR(MAX) = N'KILL '''+ @session_id + '''';
        EXEC [sp_executesql] @sql_stmt;
        DELETE FROM #SessionIDs WHERE session_id = @session_id;
    END
END
DROP TABLE #SessionIDs;

